window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-515213fd5a9c2b2e"]={"versions": [{"id": "FIG-515213fd5a9c2b2e", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische PDU-Layout-Spezifikation (Bit-/Byte-Struktur) für eine AUTOSAR CAN Network Management PDU (NM PDU) mit Partial Networking (PN) Information im Kontext des BSW-Moduls <code>CanNm</code>. Das Schaubild visualisiert die Zuordnung und Belegung einer 8-Byte langen PDU payload (<code>PduInfoType.SduDataPtr</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Entität ist ein 8-Byte PDU-Frame (Byte 0 bis Byte 7):</p>\n<ul class=\"fig-list\"><li><strong>Byte 0 (CBV)</strong>: Control Bit Vector (Wert <code>0x40</code>), signalisiert Steuerflags (Bit 6 gesetzt = PNSR / Partial Network Learning/Bit Information Bit).\n</li><li><strong>Byte 1 (NID)</strong>: Node Identifier (Wert <code>0x00</code>), logische Quell-Knotenadresse.\n</li><li><strong>Byte 2 &amp; 3 (User Data)</strong>: Anwenderdaten / User Data Bytes (Werte jeweils <code>0xFF</code>).\n</li><li><strong>Byte 4 &amp; 5 (PN Info)</strong>: Partial Network Cluster Information Vector (Werte <code>0x12</code> und <code>0x8E</code>), kodiert die angeforderten/aktiven Partial Networks über Bitmasken.\n</li><li><strong>Byte 6 &amp; 7 (User Data)</strong>: Weitere Anwenderdaten / User Data Bytes (Werte jeweils <code>0xFF</code>).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen: PDU-Austausch zwischen CAN-Treiber/Interface (<code>CanIf</code>), <code>CanNm</code> und dem PDU Router (<code>PduR</code>) bzw. <code>ComM</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Payload-Muster einer periodisch oder ereignisgesteuert übertragenen NM-Botschaft. Bei Aufruf von <code>CanNm_Transmit()</code> oder <code>CanNm_MainFunction()</code> wird der PDU-Puffer assembliert: CBV und NID werden gemäß Konfiguration an Offset 0 und 1 platziert, gefolgt von User Data und den durch den PN-Filter/Kommunikationsmanager bereitgestellten PN-Vektordaten in Bytes 4 und 5. Empfängerseitig extrahiert die CanNm-Instanz das PN-Info-Feld, filtert auf relevante Partial Networks und leitet Statusänderungen an den <code>ComM</code> weiter.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Beispiel-Layout für die Konfiguration des NM-PDU-Aufbaus mit aktivierter Partial Networking Unterstützung (<code>CANNM_PN_SUPPORT = TRUE</code>). Die Positionierung von CBV auf Byte 0 (<code>CANNM_PDU_BYTE_0</code>), NID auf Byte 1 (<code>CANNM_PDU_BYTE_1</code>), des PN-Info-Vektors auf den parametrierten Bytes 4–5 (<code>CANNM_PN_INFO_OFFSET = 4</code>, <code>CANNM_PN_INFO_LENGTH = 2</code>) sowie die Belegung der umgebenden Bytes als User Data müssen bei der Parametrierung der BSW-Konfiguration konsistent abgestimmt sein.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ce5a72212d9b5d71", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische PDU-Layout-Spezifikation (Bit-/Byte-Struktur) für eine AUTOSAR CAN Network Management PDU (NM PDU) mit Partial Networking (PN) Information im Kontext des BSW-Moduls <code>CanNm</code>. Das Schaubild visualisiert die Zuordnung und Belegung einer 8-Byte langen PDU payload (<code>PduInfoType.SduDataPtr</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Entität ist ein 8-Byte PDU-Frame (Byte 0 bis Byte 7):</p>\n<ul class=\"fig-list\"><li><strong>Byte 0 (CBV)</strong>: Control Bit Vector (Wert <code>0x40</code>), signalisiert Steuerflags (Bit 6 gesetzt = PNSR / Partial Network Learning/Bit Information Bit).\n</li><li><strong>Byte 1 (NID)</strong>: Node Identifier (Wert <code>0x00</code>), logische Quell-Knotenadresse.\n</li><li><strong>Byte 2 &amp; 3 (User Data)</strong>: Anwenderdaten / User Data Bytes (Werte jeweils <code>0xFF</code>).\n</li><li><strong>Byte 4 &amp; 5 (PN Info)</strong>: Partial Network Cluster Information Vector (Werte <code>0x12</code> und <code>0x8E</code>), kodiert die angeforderten/aktiven Partial Networks über Bitmasken.\n</li><li><strong>Byte 6 &amp; 7 (User Data)</strong>: Weitere Anwenderdaten / User Data Bytes (Werte jeweils <code>0xFF</code>).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen: PDU-Austausch zwischen CAN-Treiber/Interface (<code>CanIf</code>), <code>CanNm</code> und dem PDU Router (<code>PduR</code>) bzw. <code>ComM</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Payload-Muster einer periodisch oder ereignisgesteuert übertragenen NM-Botschaft. Bei Aufruf von <code>CanNm_Transmit()</code> oder <code>CanNm_MainFunction()</code> wird der PDU-Puffer assembliert: CBV und NID werden gemäß Konfiguration an Offset 0 und 1 platziert, gefolgt von User Data und den durch den PN-Filter/Kommunikationsmanager bereitgestellten PN-Vektordaten in Bytes 4 und 5. Empfängerseitig extrahiert die CanNm-Instanz das PN-Info-Feld, filtert auf relevante Partial Networks und leitet Statusänderungen an den <code>ComM</code> weiter.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Beispiel-Layout für die Konfiguration des NM-PDU-Aufbaus mit aktivierter Partial Networking Unterstützung (<code>CANNM_PN_SUPPORT = TRUE</code>). Die Positionierung von CBV auf Byte 0 (<code>CANNM_PDU_BYTE_0</code>), NID auf Byte 1 (<code>CANNM_PDU_BYTE_1</code>), des PN-Info-Vektors auf den parametrierten Bytes 4–5 (<code>CANNM_PN_INFO_OFFSET = 4</code>, <code>CANNM_PN_INFO_LENGTH = 2</code>) sowie die Belegung der umgebenden Bytes als User Data müssen bei der Parametrierung der BSW-Konfiguration konsistent abgestimmt sein.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-fb8dd30f6ec20bf2", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische PDU-Layout-Spezifikation (Bit-/Byte-Struktur) für eine AUTOSAR CAN Network Management PDU (NM PDU) mit Partial Networking (PN) Information im Kontext des BSW-Moduls <code>CanNm</code>. Das Schaubild visualisiert die Zuordnung und Belegung einer 8-Byte langen PDU payload (<code>PduInfoType.SduDataPtr</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Entität ist ein 8-Byte PDU-Frame (Byte 0 bis Byte 7):</p>\n<ul class=\"fig-list\"><li><strong>Byte 0 (CBV)</strong>: Control Bit Vector (Wert <code>0x40</code>), signalisiert Steuerflags (Bit 6 gesetzt = PNSR / Partial Network Learning/Bit Information Bit).\n</li><li><strong>Byte 1 (NID)</strong>: Node Identifier (Wert <code>0x00</code>), logische Quell-Knotenadresse.\n</li><li><strong>Byte 2 &amp; 3 (User Data)</strong>: Anwenderdaten / User Data Bytes (Werte jeweils <code>0xFF</code>).\n</li><li><strong>Byte 4 &amp; 5 (PN Info)</strong>: Partial Network Cluster Information Vector (Werte <code>0x12</code> und <code>0x8E</code>), kodiert die angeforderten/aktiven Partial Networks über Bitmasken.\n</li><li><strong>Byte 6 &amp; 7 (User Data)</strong>: Weitere Anwenderdaten / User Data Bytes (Werte jeweils <code>0xFF</code>).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen: PDU-Austausch zwischen CAN-Treiber/Interface (<code>CanIf</code>), <code>CanNm</code> und dem PDU Router (<code>PduR</code>) bzw. <code>ComM</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Payload-Muster einer periodisch oder ereignisgesteuert übertragenen NM-Botschaft. Bei Aufruf von <code>CanNm_Transmit()</code> oder <code>CanNm_MainFunction()</code> wird der PDU-Puffer assembliert: CBV und NID werden gemäß Konfiguration an Offset 0 und 1 platziert, gefolgt von User Data und den durch den PN-Filter/Kommunikationsmanager bereitgestellten PN-Vektordaten in Bytes 4 und 5. Empfängerseitig extrahiert die CanNm-Instanz das PN-Info-Feld, filtert auf relevante Partial Networks und leitet Statusänderungen an den <code>ComM</code> weiter.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Beispiel-Layout für die Konfiguration des NM-PDU-Aufbaus mit aktivierter Partial Networking Unterstützung (<code>CANNM_PN_SUPPORT = TRUE</code>). Die Positionierung von CBV auf Byte 0 (<code>CANNM_PDU_BYTE_0</code>), NID auf Byte 1 (<code>CANNM_PDU_BYTE_1</code>), des PN-Info-Vektors auf den parametrierten Bytes 4–5 (<code>CANNM_PN_INFO_OFFSET = 4</code>, <code>CANNM_PN_INFO_LENGTH = 2</code>) sowie die Belegung der umgebenden Bytes als User Data müssen bei der Parametrierung der BSW-Konfiguration konsistent abgestimmt sein.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-515213fd5a9c2b2e", "to": "FIG-ce5a72212d9b5d71", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ce5a72212d9b5d71", "to": "FIG-fb8dd30f6ec20bf2", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
